const today = new Date();
const dayIndex = today.getDay();

const getWeekNumber = (d) => {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const dayNum = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
};
const weekNum = getWeekNumber(today);
const isOddWeek = weekNum % 2 !== 0;

// Mon/Wed/Fri posts — 2 alternating content types per day
const configMap = {
  1: isOddWeek
    ? {
        category: 'Why Professional Management',
        postType: 'education',
        topic: 'Most luxury villa owners in Riviera Nayarit leave significant revenue on the table. Not because of bad properties — but because managing guests, staff, and bookings is a full-time job that most owners cannot do from a distance.',
        audience: 'Luxury property owners in Punta de Mita, Sayulita, San Pancho',
        postStyle: 'Insightful, direct, speaks to pain points — long-distance ownership, missed bookings, staff issues',
        ctaStyle: 'DM us or message on WhatsApp to learn how LUX can manage your property',
        hookExample: 'Owning a luxury villa in Riviera Nayarit should feel like an asset. Not a second job.',
        pexelsQuery: 'Sayulita Mexico beach village palm trees tropical'
      }
    : {
        category: 'Revenue Optimization',
        postType: 'revenue',
        topic: 'LUX owners consistently outperform the market. Direct booking channels, strategic pricing, premium concierge that drives 5-star reviews, and the right guest profile. Every decision we make is oriented around your return.',
        audience: 'Property owners who want to maximize rental income',
        postStyle: 'Confident, data-implied, business-minded but not cold',
        ctaStyle: 'Ask us about revenue potential for your property — DM or WhatsApp',
        hookExample: 'Your villa generates revenue while you sleep. That is what proper management looks like.',
        pexelsQuery: 'Sayulita Mexico ocean view terrace pool villa outdoor'
      },
  3: isOddWeek
    ? {
        category: 'Full-Service Staffing',
        postType: 'services',
        topic: 'LUX handles everything: private chefs, professional housekeepers, concierge, airport transfers, activity bookings. The staff we bring in are vetted, trained, and represent your property as their own. Guests feel it immediately.',
        audience: 'Property owners tired of managing staff or dealing with guest complaints',
        postStyle: 'Reassuring, operational, shows depth of service',
        ctaStyle: 'Learn how we staff and operate your property — DM or WhatsApp',
        hookExample: 'A private chef. A concierge who knows every restaurant in Sayulita. Housekeeping that leaves a review.',
        pexelsQuery: 'private chef cooking outdoor kitchen Mexico tropical villa'
      }
    : {
        category: 'Direct Booking Advantage',
        postType: 'strategy',
        topic: 'Every booking through Airbnb or VRBO costs your property 15–20% in platform fees. LUX builds and manages direct booking websites for your property, retains repeat guests, and builds the brand around your villa — not the platform.',
        audience: 'Property owners frustrated with OTA fees and lack of control',
        postStyle: 'Strategic, slightly provocative, positions LUX as forward-thinking',
        ctaStyle: 'Ask us how we reduce OTA dependency — DM or WhatsApp',
        hookExample: 'Airbnb and VRBO take up to 20% of your revenue. There is a better way.',
        pexelsQuery: 'Riviera Nayarit Mexico beach sunset palm Nayarit coast'
      },
  5: isOddWeek
    ? {
        category: 'Riviera Nayarit Luxury Market',
        postType: 'market',
        topic: 'Punta de Mita, Sayulita, and San Pancho are among the fastest-growing luxury destinations in Latin America. International demand for high-end villa rentals is accelerating. Owners who invest in professional management now are building long-term asset value.',
        audience: 'Property owners and investors interested in the Riviera Nayarit market',
        postStyle: 'Market-informed, aspirational, positions LUX as the insider',
        ctaStyle: 'Talk to us about your property — DM or WhatsApp',
        hookExample: 'Riviera Nayarit is not a trend. It is one of Mexico\'s most sought-after luxury markets.',
        pexelsQuery: 'Punta Mita Mexico beach surf tropical Pacific coast Nayarit'
      }
    : {
        category: 'Owner Transparency',
        postType: 'technology',
        topic: 'LUX owners have full visibility into their property at all times — booking calendar, revenue dashboard, maintenance logs, guest reviews. No surprises. No mystery. Just a clear picture of how your asset is performing.',
        audience: 'Property owners who value accountability and visibility',
        postStyle: 'Trust-building, professional, positions LUX as reliable and accountable',
        ctaStyle: 'See how our owner dashboard works — DM or WhatsApp',
        hookExample: 'You should know exactly what is happening at your property. Always.',
        pexelsQuery: 'Mexico villa outdoor terrace ocean view Nayarit Pacific coast'
      }
};

const cfg = configMap[dayIndex] || configMap[1];

return [{
  json: {
    dayIndex,
    dayName: ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][dayIndex],
    runDate: today.toISOString().split('T')[0],
    weekNum,
    category: cfg.category,
    postType: cfg.postType,
    topic: cfg.topic,
    audience: cfg.audience,
    postStyle: cfg.postStyle,
    ctaStyle: cfg.ctaStyle,
    hookExample: cfg.hookExample,
    pexelsQuery: cfg.pexelsQuery
  }
}];

const prev = $input.first();
const photos = prev.json.photos || [];

if (photos.length === 0) {
  throw new Error('No Pexels photos returned for query: ' + prev.json.pexelsQuery);
}

const shuffled = photos.sort(() => Math.random() - 0.5);
const selected = shuffled.slice(0, 3);

const dayConfig = $('Get Day Config').first().json;

return selected.map((p, i) => ({
  json: {
    ...dayConfig,
    photoIndex: i,
    photoUrl: p.src.large2x || p.src.large,
    photoId: p.id,
    photographer: p.photographer
  }
}));

const items = $input.all();
const photoIds = items.map(i => i.json.id).filter(Boolean);

if (photoIds.length === 0) {
  throw new Error('No photos uploaded to Facebook successfully');
}

const dayConfig = $('Get Day Config').first().json;

return [{ json: { ...dayConfig, photoIds } }];

const item = $input.first();

const systemPrompt = `You are the social media content creator for LUX Property Management, a full-service luxury property management company operating in Riviera Nayarit, Mexico — Punta de Mita, Sayulita, and San Pancho.

ABOUT LUX PROPERTY MANAGEMENT:
- Full-service management for luxury villas and estates in Riviera Nayarit
- Services: professional staffing (concierge, private chefs, housekeepers, cleaning crews), direct booking website creation and management, strategic revenue optimization, premium concierge service, top-of-the-line property management system with full owner transparency
- Focus on luxury properties, large groups, high-end guest experiences
- Region: Punta de Mita, Sayulita, San Pancho, Riviera Nayarit, Nayarit, Mexico — one of Latin America's fastest-growing luxury destinations
- Managed properties include luxury villas and estates with pools, ocean views, private chefs, and concierge services

TARGET AUDIENCE: Luxury property owners in Riviera Nayarit who want to maximize their rental income, reduce the stress of remote management, and work with a trusted local partner.

CONTENT GOAL: Generate leads — property owners should feel understood, see the value of professional management, and want to reach out to LUX for a conversation.

CTA: Invite them to DM on Facebook or contact via WhatsApp. No website yet.

ABSOLUTE RULES:
- Owner-facing only — never write from a guest booking perspective
- No markdown: no asterisks, no bold, no headers, no bullet points
- Plain text only
- 100-200 words excluding hashtags
- Hashtags at the very end only
- Never mention specific commission rates or pricing
- Never claim services LUX does not offer

BRAND VOICE:
- Professional, knowledgeable, warm — a trusted local partner, not a corporate vendor
- Confident about the Riviera Nayarit market and what premium management delivers
- Speak directly to the property owner: ROI, peace of mind, quality guests, zero headaches
- Lead with a sharp insight, question, or statement that resonates with luxury property owners
- Understands the difference between owning a property and operating one

POST STRUCTURE:
1. Hook (1-2 lines): A question, sharp insight, or provocative statement aimed at luxury property owners
2. Body (2-3 paragraphs): Value-driven, specific to today's category, grounded in real LUX capabilities
3. CTA: Invite them to DM or WhatsApp — soft, professional, not pushy
4. Hashtags: 5-7 relevant ones at the very end

HASHTAGS TO DRAW FROM: #LUXPropertyManagement #RivieraNayarit #PuntaDeMita #Sayulita #SanPancho #LuxuryVillaManagement #PropertyManagement #MexicoVilla #VacationRentalManagement #DirectBooking #VillaManagement #LuxuryTravel #NayaritMexico #VillaOwner`;

const userPrompt = `Generate a Facebook post for LUX Property Management.

Today's category: ${item.json.category}
Post type: ${item.json.postType}
Topic focus: ${item.json.topic}
Audience: ${item.json.audience}
Post style: ${item.json.postStyle}
CTA: ${item.json.ctaStyle}
Hook reference (adapt freely, don't copy): ${item.json.hookExample}

Plain text only. No markdown. 100-200 words. Hashtags at end only. Output the post and nothing else.`;

return [{
  json: {
    ...item.json,
    claudeRequestBody: JSON.stringify({
      model: 'claude-opus-4-6',
      max_tokens: 1024,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    })
  }
}];

const item = $input.first();
const content = item.json.content;

if (!content || !Array.isArray(content) || content.length === 0) {
  throw new Error('Claude returned empty content: ' + JSON.stringify(item.json));
}

const caption = content[0].text?.trim();
if (!caption || caption.length < 50) {
  throw new Error('Caption too short or missing: ' + caption);
}

const prevData = $('Collect Upload Results').first().json;

return [{
  json: {
    ...prevData,
    caption
  }
}];

const item = $input.first();

const attachedMedia = item.json.photoIds.map(id => ({ media_fbid: id }));

const postBody = {
  message: item.json.caption,
  attached_media: attachedMedia,
  published: true
};

return [{
  json: {
    ...item.json,
    postBody: JSON.stringify(postBody)
  }
}];

const err = $input.first().json;
console.error('LUX Social Post Error:', JSON.stringify(err, null, 2));
return $input.all();
